import{_ as t,o as i,c as e,a2 as s}from"./chunks/framework.CtrpDQpp.js";const l="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",o="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",r="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",n="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",d="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",h="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",p="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",c="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",g="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",_=JSON.parse('{"title":"第 19 章 性能优化插件","description":"","frontmatter":{},"headers":[],"relativePath":"19-performance-plugins.md","filePath":"19-performance-plugins.md","lastUpdated":1792595797000}'),A={name:"19-performance-plugins.md"};function k(u,a,m,b,C,P){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="第-19-章-性能优化插件" tabindex="-1">第 19 章 性能优化插件 <a class="header-anchor" href="#第-19-章-性能优化插件" aria-label="Permalink to &quot;第 19 章 性能优化插件&quot;">​</a></h1><p>🟡 <strong>进阶难度</strong> ｜ 一句话导览：性能优化不是「装个缓存插件就完事」，而是理解浏览器缓存、页面缓存、对象缓存、OPcache、CDN 五层架构，按需组合。本章以 WP Super Cache 为例做点击级配置，讲透 Redis 对象缓存、数据库优化、资源压缩合并的利与弊，并给出缓存穿透、样式错乱、JS 依赖破坏三大事故的排查顺序。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>画出 WordPress 性能优化的五层缓存架构，理解每层的作用与适用场景</li><li>完成 WP Super Cache 的简单模式配置，理解「预缓存」与「垃圾回收」的区别</li><li>在服务器装好 Redis 的前提下，配置 Redis Object Cache 插件实现对象缓存</li><li>掌握数据库优化：修订版本、草稿、瞬态（transient）的清理策略</li><li>理解资源压缩合并的原理，以及 HTTP/2 时代「合并」是否仍然必要的争议</li><li>配置延迟加载（Lazy Load）与延迟 JS，提升首屏速度</li><li>遇到缓存导致登录用户看到他人页面、改 CSS 不生效、压缩合并破坏 JS 依赖时，能按层级排查</li></ul><h2 id="_19-1-缓存分层-五层架构全景" tabindex="-1">19.1 缓存分层：五层架构全景 <a class="header-anchor" href="#_19-1-缓存分层-五层架构全景" aria-label="Permalink to &quot;19.1 缓存分层：五层架构全景&quot;">​</a></h2><h3 id="_19-1-1-原理说明" tabindex="-1">19.1.1 原理说明 <a class="header-anchor" href="#_19-1-1-原理说明" aria-label="Permalink to &quot;19.1.1 原理说明&quot;">​</a></h3><p>WordPress 的性能问题本质是「每次请求都要重复计算」：查数据库、组装页面、输出 HTML。缓存的思想是「把计算结果存起来，下次直接用」。但「存起来」发生在多个层级，每层解决不同瓶颈：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[用户浏览器] --&gt;|1. 浏览器缓存&lt;br/&gt;静态资源本地存| B[CDN 边缘节点&lt;br/&gt;2. CDN 缓存&lt;br/&gt;全球分发]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|3. 页面缓存&lt;br/&gt;整页 HTML 存磁盘/内存| C[Web 服务器]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|4. 对象缓存&lt;br/&gt;数据库查询结果存 Redis| D[PHP/WordPress]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|5. OPcache&lt;br/&gt;PHP 字节码存内存| E[PHP 解释器]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>层级</th><th>名称</th><th>存什么</th><th>生效位置</th><th>由谁负责</th></tr></thead><tbody><tr><td>1</td><td>浏览器缓存</td><td>CSS/JS/图片</td><td>用户电脑</td><td>服务器响应头（Cache-Control）</td></tr><tr><td>2</td><td>CDN 缓存</td><td>静态资源 + 整页 HTML</td><td>全球边缘节点</td><td>Cloudflare/阿里云 CDN 等</td></tr><tr><td>3</td><td>页面缓存</td><td>完整 HTML 页面</td><td>服务器磁盘或内存</td><td>WP Super Cache 等插件</td></tr><tr><td>4</td><td>对象缓存</td><td>数据库查询结果</td><td>服务器内存（Redis/Memcached）</td><td>Redis Object Cache 等插件</td></tr><tr><td>5</td><td>OPcache</td><td>PHP 编译后的字节码</td><td>PHP 进程内存</td><td>php.ini 配置</td></tr></tbody></table><p><strong>关键认知</strong>：五层是叠加关系，不是替代关系。一个小站可能只需要第 3 层（页面缓存）+ 第 1 层（浏览器缓存）；一个高并发站可能需要全部五层。本章主要讲第 3、4 层（插件可控），第 1、2、5 层的基础配置见<a href="./29-performance">第 29 章</a>。</p><h3 id="_19-1-2-操作方法-评估你的瓶颈在哪一层" tabindex="-1">19.1.2 操作方法：评估你的瓶颈在哪一层 <a class="header-anchor" href="#_19-1-2-操作方法-评估你的瓶颈在哪一层" aria-label="Permalink to &quot;19.1.2 操作方法：评估你的瓶颈在哪一层&quot;">​</a></h3><p>在动手装插件之前，先判断瓶颈：</p><table tabindex="0"><thead><tr><th>症状</th><th>大概率瓶颈层</th><th>验证方法</th></tr></thead><tbody><tr><td>首页打开慢，但后台不慢</td><td>第 3 层（页面缓存缺失）</td><td>查看页面源代码底部是否有 <code>&lt;!-- Cached page generated by WP-Super-Cache --&gt;</code></td></tr><tr><td>后台列表页、搜索页慢</td><td>第 4 层（对象缓存缺失）</td><td>安装 Query Monitor 插件，看数据库查询次数是否 &gt;100</td></tr><tr><td>所有 PHP 页面都慢，连 <code>phpinfo()</code> 都慢</td><td>第 5 层（OPcache 未开）</td><td><code>php -v</code> 或 <code>phpinfo()</code> 查看 OPcache 是否启用</td></tr><tr><td>静态资源（图片/CSS）加载慢</td><td>第 1、2 层（浏览器缓存/CDN）</td><td>浏览器开发者工具 Network 面板看资源响应头有无 <code>cache-control</code></td></tr></tbody></table><blockquote><p>💡 Query Monitor 是性能排查的瑞士军刀，能精确到「哪个插件的哪次查询花了多少毫秒」。本章练习会用到它。</p></blockquote><h3 id="_19-1-3-常见问题" tabindex="-1">19.1.3 常见问题 <a class="header-anchor" href="#_19-1-3-常见问题" aria-label="Permalink to &quot;19.1.3 常见问题&quot;">​</a></h3><p><strong>问：装了页面缓存插件，后台会变慢吗？</strong> 通常不会。页面缓存插件默认对登录用户不缓存（因为后台内容千人千面），但某些配置错误可能导致「登录用户看到他人缓存页」（19.9.1 节会专门讲）。后台慢通常是对象缓存缺失或数据库未优化。</p><p><strong>问：CDN 和页面缓存冲突吗？</strong> 不冲突，是互补。页面缓存解决「源站生成 HTML 慢」，CDN 解决「用户离源站远、网络延迟高」。正确姿势是：页面缓存插件生成 HTML → CDN 把 HTML 缓存到边缘节点 → 用户从最近节点获取。</p><h2 id="_19-2-页面缓存插件配置" tabindex="-1">19.2 页面缓存插件配置 <a class="header-anchor" href="#_19-2-页面缓存插件配置" aria-label="Permalink to &quot;19.2 页面缓存插件配置&quot;">​</a></h2><h3 id="_19-2-1-wp-super-cache-简单模式" tabindex="-1">19.2.1 WP Super Cache 简单模式 <a class="header-anchor" href="#_19-2-1-wp-super-cache-简单模式" aria-label="Permalink to &quot;19.2.1 WP Super Cache 简单模式&quot;">​</a></h3><h4 id="原理说明" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明" aria-label="Permalink to &quot;原理说明&quot;">​</a></h4><p>WP Super Cache 是 Automattic 官方出品的页面缓存插件，原理是：当匿名用户访问页面时，PHP 把生成的 HTML 存为静态文件（<code>wp-content/cache/supercache/域名/页面/index.html</code>）；下次访问同一页面时，Web 服务器直接返回静态文件，不再执行 PHP 与数据库查询。</p><p>它有两种模式：</p><ul><li><strong>简单模式（Simple）</strong>：用 PHP 判断缓存文件是否存在并输出，兼容性好，速度稍慢（仍需启动 PHP）。</li><li><strong>专家模式（Expert）</strong>：用 Apache/Nginx 重写规则直接返回静态文件，完全不启动 PHP，速度最快，但需手动配置服务器规则。</li></ul><h4 id="操作方法-点击级配置" tabindex="-1">操作方法：点击级配置 <a class="header-anchor" href="#操作方法-点击级配置" aria-label="Permalink to &quot;操作方法：点击级配置&quot;">​</a></h4><ol><li>后台「插件 → 安装插件」，搜索 <code>WP Super Cache</code>，安装并启用。</li><li>进入「设置 → WP Super Cache」。</li><li>「简单」标签页： <ul><li>「缓存启用」：勾选「启用缓存」。</li><li>「缓存方式」：选择「简单（推荐）」。</li><li>点击「更新」。</li></ul></li><li>「高级」标签页（关键选项）： <ul><li>「缓存访问此站点的已知用户」：<strong>不要勾选</strong>——登录用户不缓存，避免看到他人内容。</li><li>「不缓存已登录用户的页面」：勾选（默认）。</li><li>「缓存重建」：勾选。缓存过期时，先生成新缓存再删旧缓存，避免访客看到「生成中」的空白。</li><li>「304 浏览器缓存」：勾选。配合浏览器缓存减少重复传输。</li></ul></li><li>「预缓存」标签页： <ul><li>「预缓存模式」：勾选。插件会按你设定的间隔自动爬取全站页面生成缓存，确保任何页面第一次访问就有缓存。</li><li>「预缓存更新间隔」：默认 30 分钟。内容更新频繁的站可改为 10 分钟；静态站可改为 1440 分钟（一天）。</li></ul></li><li>「垃圾回收」标签页： <ul><li>「缓存超时时间」：默认 3600 秒（1 小时）。过期缓存会被删除，避免磁盘占用无限增长。</li><li>「计划任务」：保持默认，插件会定期清理过期文件。</li></ul></li></ol><p><img src="`+l+'" alt="图 19-1：WP Super Cache 简单模式主设置页"></p><p><em>图 19-1：简单模式适合绝大多数站点；专家模式需要手动配置 Nginx/Apache 规则。</em></p><p><img src="'+o+`" alt="图 19-2：预缓存与垃圾回收设置"></p><p><em>图 19-2：预缓存确保「第一次访问就快」，垃圾回收防止磁盘被缓存塞满。</em></p><p><strong>验证缓存是否生效</strong>：</p><ol><li>用无痕窗口（未登录）访问首页。</li><li>查看页面源代码，拉到最底部，应看到类似 <code>&lt;!-- Cached page generated by WP-Super-Cache on 2026-10-04 10:00:00 --&gt;</code> 的注释。</li><li>再次刷新，注释时间不变，说明命中缓存。</li></ol><h3 id="_19-2-2-w3-total-cache-概览" tabindex="-1">19.2.2 W3 Total Cache 概览 <a class="header-anchor" href="#_19-2-2-w3-total-cache-概览" aria-label="Permalink to &quot;19.2.2 W3 Total Cache 概览&quot;">​</a></h3><p>W3 Total Cache 是功能更全的老牌插件：页面缓存、对象缓存、数据库缓存、浏览器缓存、CDN 集成、压缩合并，一站式解决。但正因为功能多，配置复杂度高，新手容易「全开导致冲突」。建议：先用 WP Super Cache 跑通页面缓存，理解原理后再评估是否需要 W3 Total Cache 的对象缓存与 CDN 集成。</p><h3 id="_19-2-3-商用-wp-rocket-提一句" tabindex="-1">19.2.3 商用 WP Rocket 提一句 <a class="header-anchor" href="#_19-2-3-商用-wp-rocket-提一句" aria-label="Permalink to &quot;19.2.3 商用 WP Rocket 提一句&quot;">​</a></h3><p>WP Rocket 是付费插件（$59/年起），优势是「开箱即用」——激活后自动开启页面缓存、浏览器缓存、Gzip、延迟加载，无需配置。如果你不想研究参数、愿意付费换时间，WP Rocket 是省心之选；如果你想理解原理、控制每一层，免费插件 + 手工配置更适合学习。</p><h3 id="_19-2-4-页面缓存的排除列表配置" tabindex="-1">19.2.4 页面缓存的排除列表配置 <a class="header-anchor" href="#_19-2-4-页面缓存的排除列表配置" aria-label="Permalink to &quot;19.2.4 页面缓存的排除列表配置&quot;">​</a></h3><p><strong>原理</strong>：某些页面绝不能被缓存：购物车、结账页、我的账户、密码重置页——这些页面内容是用户私有的，如果缓存给另一个用户看到，就是严重的数据泄露。</p><p><strong>操作方法</strong>：在 WP Super Cache「高级 → 拒绝的 URL 字符串」中添加：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/cart/</span></span>
<span class="line"><span>/checkout/</span></span>
<span class="line"><span>/my-account/</span></span>
<span class="line"><span>/wp-admin/</span></span></code></pre></div><p>WooCommerce 等电商插件会自动告诉缓存插件哪些页面需要排除，但手动检查一遍更稳妥。此外，查询参数带 <code>?s=</code>（搜索）或 <code>?add-to-cart=</code> 的 URL 也应排除——缓存搜索结果会导致不同搜索词返回同一页面。</p><h3 id="_19-2-5-常见问题" tabindex="-1">19.2.5 常见问题 <a class="header-anchor" href="#_19-2-5-常见问题" aria-label="Permalink to &quot;19.2.5 常见问题&quot;">​</a></h3><p><strong>问：预缓存会把服务器爬崩吗？</strong> 不会。WP Super Cache 的预缓存是「逐个页面、间隔几秒」的温和爬取，不是并发轰炸。但如果站点有几千个页面且服务器性能差，可把预缓存间隔拉长到 1440 分钟，或改用「仅预缓存最新文章」。</p><p><strong>问：开启缓存后，后台发布文章前台不更新？</strong> 检查「高级 → 不缓存已登录用户的页面」是否勾选（应该勾选）；检查「垃圾回收 → 缓存超时时间」是否过长；手动到「内容 → 删除缓存」清一次。理想配置是：发布/更新文章时插件自动清除该页面缓存（WP Super Cache 默认支持）。</p><h2 id="_19-3-对象缓存-redis" tabindex="-1">19.3 对象缓存 Redis <a class="header-anchor" href="#_19-3-对象缓存-redis" aria-label="Permalink to &quot;19.3 对象缓存 Redis&quot;">​</a></h2><h3 id="_19-3-1-原理说明" tabindex="-1">19.3.1 原理说明 <a class="header-anchor" href="#_19-3-1-原理说明" aria-label="Permalink to &quot;19.3.1 原理说明&quot;">​</a></h3><p>对象缓存把「数据库查询结果」存到内存数据库（Redis/Memcached）。WordPress 的 <code>wp_options</code>、<code>wp_posts</code>、<code>wp_postmeta</code> 等表的查询结果，第一次查询后存入 Redis，后续相同查询直接从内存返回，不再走 MySQL。对后台列表页、复杂归档页、WooCommerce 商品筛选页提速显著。</p><p><strong>前提</strong>：服务器必须已安装并运行 Redis 服务。本地开发可用 Docker；生产服务器可用包管理器安装（<code>sudo apt install redis-server</code> 或宝塔面板一键安装）。</p><h3 id="_19-3-2-操作方法-安装与配置" tabindex="-1">19.3.2 操作方法：安装与配置 <a class="header-anchor" href="#_19-3-2-操作方法-安装与配置" aria-label="Permalink to &quot;19.3.2 操作方法：安装与配置&quot;">​</a></h3><ol><li>确认 Redis 已运行：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ping</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 应返回 PONG</span></span></code></pre></div></li><li>后台安装并启用 <code>Redis Object Cache</code> 插件（Till Krüss 版，官方库排名第一）。</li><li>进入「设置 → Redis」。</li><li>点击「启用对象缓存」。插件会自动在 <code>wp-content/</code> 下生成 <code>object-cache.php</code> 文件（这是 WordPress 的对象缓存 drop-in 机制）。</li><li>状态应显示「已连接」，并显示 Redis 版本、内存占用、命中率。</li></ol><p><img src="`+r+`" alt="图 19-3：Redis Object Cache 设置页，显示已连接与命中率"></p><p><em>图 19-3：启用后状态页显示连接信息与命中率，命中率 &gt;90% 说明配置正确。</em></p><p><strong>验证对象缓存生效</strong>：</p><ol><li>安装 Query Monitor 插件。</li><li>刷新后台「文章 → 所有文章」。</li><li>查看 Query Monitor 的「数据库查询」面板，第一次刷新可能 50+ 次查询，第二次刷新应降到 10 次以内——因为大部分查询走了 Redis。</li></ol><h3 id="_19-3-3-常见问题" tabindex="-1">19.3.3 常见问题 <a class="header-anchor" href="#_19-3-3-常见问题" aria-label="Permalink to &quot;19.3.3 常见问题&quot;">​</a></h3><p><strong>问：启用对象缓存后，某些插件数据不更新？</strong> 极少数插件直接写数据库而不通过 WordPress API（如 <code>wpdb-&gt;query</code> 手写 SQL），导致对象缓存中的旧数据未被清除。解法：到「设置 → Redis」点击「刷新缓存」，或联系插件作者改用 <code>wp_update_post()</code> 等标准 API。</p><p><strong>问：Redis 与 Memcached 选哪个？</strong> Redis 功能更丰富（支持持久化、更复杂的数据结构），社区生态更好；Memcached 更轻量。对 WordPress 对象缓存场景，两者性能差异不大，推荐 Redis（插件支持更好）。</p><h2 id="_19-4-数据库优化" tabindex="-1">19.4 数据库优化 <a class="header-anchor" href="#_19-4-数据库优化" aria-label="Permalink to &quot;19.4 数据库优化&quot;">​</a></h2><h3 id="_19-4-1-原理说明" tabindex="-1">19.4.1 原理说明 <a class="header-anchor" href="#_19-4-1-原理说明" aria-label="Permalink to &quot;19.4.1 原理说明&quot;">​</a></h3><p>WordPress 数据库会随时间积累「垃圾数据」：</p><ul><li><strong>文章修订版本</strong>：每次保存草稿/更新，旧版本都保留。一篇改 20 次的文章会有 20 条修订记录。</li><li><strong>自动草稿</strong>：新建文章时自动生成的空草稿。</li><li><strong>回收站文章/评论</strong>：删除后进入回收站，30 天后才真正删除。</li><li><strong>过期瞬态（Transient）</strong>：插件缓存的临时数据，设计为自动过期，但过期后仍留在数据库。</li></ul><p>这些垃圾数据会拖慢查询速度，尤其是 <code>wp_posts</code> 与 <code>wp_postmeta</code> 表。</p><h3 id="_19-4-2-操作方法-清理与限制" tabindex="-1">19.4.2 操作方法：清理与限制 <a class="header-anchor" href="#_19-4-2-操作方法-清理与限制" aria-label="Permalink to &quot;19.4.2 操作方法：清理与限制&quot;">​</a></h3><p><strong>限制修订版本数量</strong>（<code>wp-config.php</code>）：</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 最多保留 5 个修订版本，超出自动删除最旧的。</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;WP_POST_REVISIONS&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span></code></pre></div><p><strong>清空回收站间隔</strong>（<code>wp-config.php</code>）：</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 回收站保留 7 天，默认是 30 天。</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EMPTY_TRASH_DAYS&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span></code></pre></div><p><strong>手动清理</strong>（WP-CLI）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除所有修订版本。</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> post</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> post</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --post_type=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;revision&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=ids</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--force</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除所有回收站文章。</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> post</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> post</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --post_status=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;trash&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=ids</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--force</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除过期瞬态。</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> transient</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expired</span></span></code></pre></div><p><strong>自动清理插件</strong>：WP-Optimize 或 Advanced Database Cleaner 可定时自动清理，但建议先用手动方式理解原理，再决定是否自动化。</p><p><img src="`+n+'" alt="图 19-4：WP-Optimize 的数据库清理界面"></p><p><em>图 19-4：可视化清理工具适合新手，但务必先备份数据库。</em></p><h3 id="_19-4-3-常见问题" tabindex="-1">19.4.3 常见问题 <a class="header-anchor" href="#_19-4-3-常见问题" aria-label="Permalink to &quot;19.4.3 常见问题&quot;">​</a></h3><p><strong>问：清理修订版本会影响文章内容吗？</strong> 不会。修订版本只是「历史快照」，清理后当前内容不受影响。但清理后无法回滚到某个历史版本，所以重要文章建议先手动备份或导出。</p><p><strong>问：瞬态清理会导致插件设置丢失吗？</strong> 不会。瞬态是「缓存的缓存」，清理后插件会重新生成。但某些插件把重要数据误存为瞬态（设计错误），清理后需重新配置——这是插件质量问题，不是清理操作的问题。</p><h2 id="_19-5-资源压缩合并-利与弊" tabindex="-1">19.5 资源压缩合并：利与弊 <a class="header-anchor" href="#_19-5-资源压缩合并-利与弊" aria-label="Permalink to &quot;19.5 资源压缩合并：利与弊&quot;">​</a></h2><h3 id="_19-5-1-原理说明" tabindex="-1">19.5.1 原理说明 <a class="header-anchor" href="#_19-5-1-原理说明" aria-label="Permalink to &quot;19.5.1 原理说明&quot;">​</a></h3><p>压缩（Minify）删除 CSS/JS 文件中的空白、注释、缩短变量名，减少文件体积；合并（Combine）把多个 CSS/JS 文件合并为一个，减少 HTTP 请求数。在 HTTP/1.1 时代，浏览器对同一域名最多并行 6-8 个连接，合并能显著提速。</p><h3 id="_19-5-2-http-2-下的争议" tabindex="-1">19.5.2 HTTP/2 下的争议 <a class="header-anchor" href="#_19-5-2-http-2-下的争议" aria-label="Permalink to &quot;19.5.2 HTTP/2 下的争议&quot;">​</a></h3><p>HTTP/2 支持多路复用——同一连接可并行传输多个文件，「减少请求数」的意义大幅下降。此时合并的副作用凸显：</p><ul><li><strong>缓存粒度变粗</strong>：合并后任何一个小文件改动，整个合并文件缓存失效，用户需重新下载。</li><li><strong>阻塞渲染</strong>：合并后的 JS 文件可能很大，浏览器下载并解析时阻塞首屏渲染。</li><li><strong>依赖顺序破坏</strong>：某些插件的 JS 依赖 jQuery，如果合并顺序错误，依赖关系断裂。</li></ul><p><strong>现代最佳实践</strong>：</p><ul><li>压缩（Minify）仍然推荐，无副作用。</li><li>合并（Combine）谨慎使用：HTTP/1.1 站点可合并；HTTP/2 站点建议不合并，或只合并「始终一起加载」的文件（如主题核心 CSS）。</li><li>优先用「延迟加载」与「异步加载」解决 JS 阻塞，而不是合并。</li></ul><h3 id="_19-5-3-操作方法-autoptimize-配置" tabindex="-1">19.5.3 操作方法：Autoptimize 配置 <a class="header-anchor" href="#_19-5-3-操作方法-autoptimize-配置" aria-label="Permalink to &quot;19.5.3 操作方法：Autoptimize 配置&quot;">​</a></h3><ol><li>安装并启用 <code>Autoptimize</code>。</li><li>进入「设置 → Autoptimize」。</li><li>「JavaScript 选项」： <ul><li>「优化 JavaScript 代码」：勾选（压缩）。</li><li>「合并 JS 文件」：<strong>HTTP/2 站点建议不勾选</strong>；HTTP/1.1 站点可勾选。</li><li>「异步加载 JavaScript」：勾选（非关键 JS 延迟执行）。</li></ul></li><li>「CSS 选项」： <ul><li>「优化 CSS 代码」：勾选。</li><li>「合并 CSS 文件」：同上，HTTP/2 站点建议不勾选。</li><li>「内联关键 CSS」：勾选。把首屏必需 CSS 直接嵌入 HTML，减少阻塞。</li></ul></li><li>「图片」标签页： <ul><li>「延迟加载图片」：勾选。</li></ul></li></ol><p><img src="'+d+'" alt="图 19-5：Autoptimize 的 JS/CSS 优化设置"></p><p><em>图 19-5：压缩默认开，合并视 HTTP 版本决定，异步加载与内联关键 CSS 是首屏提速关键。</em></p><h3 id="_19-5-4-常见问题" tabindex="-1">19.5.4 常见问题 <a class="header-anchor" href="#_19-5-4-常见问题" aria-label="Permalink to &quot;19.5.4 常见问题&quot;">​</a></h3><p><strong>问：压缩合并后样式错乱或 JS 报错？</strong> 99% 是「合并顺序破坏依赖」或「某个文件压缩后语法错误」。解法：到 Autoptimize 设置页，把出问题的文件加入「排除列表」（如 <code>jquery.js</code>、某个插件的 JS），或干脆关闭合并只保留压缩。</p><p><strong>问：HTTP/2 站点真的不需要合并吗？</strong> 不是绝对。如果站点有 50+ 个 CSS/JS 文件，即使 HTTP/2 多路复用，浏览器解析与执行的开销仍在。此时可「分组合并」：把「始终一起用」的文件合并为一组（如主题核心 + 常用插件），「按需加载」的文件保持独立。</p><h2 id="_19-6-cdn-接入简述" tabindex="-1">19.6 CDN 接入简述 <a class="header-anchor" href="#_19-6-cdn-接入简述" aria-label="Permalink to &quot;19.6 CDN 接入简述&quot;">​</a></h2><h3 id="_19-6-1-原理说明" tabindex="-1">19.6.1 原理说明 <a class="header-anchor" href="#_19-6-1-原理说明" aria-label="Permalink to &quot;19.6.1 原理说明&quot;">​</a></h3><p>CDN（内容分发网络）把静态资源缓存到全球边缘节点，用户从物理距离最近的节点获取资源，解决「用户离源站远、网络延迟高」的问题。它是五层架构中的第 2 层，与页面缓存（第 3 层）互补：页面缓存让源站生成 HTML 更快，CDN 让用户拿到资源更快。</p><h3 id="_19-6-2-操作方法-cloudflare-免费版接入" tabindex="-1">19.6.2 操作方法：Cloudflare 免费版接入 <a class="header-anchor" href="#_19-6-2-操作方法-cloudflare-免费版接入" aria-label="Permalink to &quot;19.6.2 操作方法：Cloudflare 免费版接入&quot;">​</a></h3><p>以最常用的 Cloudflare 免费版为例：</p><ol><li>注册 Cloudflare 账号，添加你的域名。</li><li>Cloudflare 扫描现有 DNS 记录，确认无误后，到域名注册商处把 NS 服务器改成 Cloudflare 分配的两个地址。</li><li>等待 NS 生效（几分钟到 24 小时），Cloudflare 自动开始代理流量。</li><li>在 Cloudflare 控制台的「缓存 → 配置」中，把缓存级别设为「标准」，浏览器缓存 TTL 设为「4 小时」。</li><li>「速度 → 优化」中可开启 Brotli 压缩与 Early Hints。</li></ol><p>接入后，静态资源（图片/CSS/JS）会自动缓存到全球边缘节点；整页 HTML 缓存需要配置「页面规则」（Page Rules），免费版提供 3 条规则，足够覆盖「缓存全部静态资源 + 排除后台」。</p><p><img src="'+h+'" alt="图 19-6：Cloudflare 缓存配置页"></p><p><em>图 19-6：Cloudflare 免费版即可覆盖 CDN 缓存的核心需求，页面规则控制缓存范围。</em></p><h3 id="_19-6-3-常见问题" tabindex="-1">19.6.3 常见问题 <a class="header-anchor" href="#_19-6-3-常见问题" aria-label="Permalink to &quot;19.6.3 常见问题&quot;">​</a></h3><p><strong>问：接入 CDN 后修改网站内容不更新？</strong> CDN 缓存了旧版本。到 Cloudflare「缓存 → 配置」点「清除所有内容」，或配置页面规则把 HTML 的缓存 TTL 缩短。源站的页面缓存插件与 CDN 缓存是两层独立的缓存，清一层不清另一层是「改了不生效」的最高频原因（排查顺序见 19.9.2）。</p><h2 id="_19-7-延迟加载与延迟-js" tabindex="-1">19.7 延迟加载与延迟 JS <a class="header-anchor" href="#_19-7-延迟加载与延迟-js" aria-label="Permalink to &quot;19.7 延迟加载与延迟 JS&quot;">​</a></h2><h3 id="_19-7-1-原理说明" tabindex="-1">19.7.1 原理说明 <a class="header-anchor" href="#_19-7-1-原理说明" aria-label="Permalink to &quot;19.7.1 原理说明&quot;">​</a></h3><p>延迟加载（Lazy Load）让图片/视频只在「进入视口」时才加载，首屏外的资源不下载，大幅减少首屏时间。延迟 JS（Delay JS）让非关键 JavaScript 在「用户交互后」才执行（如点击、滚动），首屏渲染不被 JS 阻塞。</p><p>WordPress 5.5+ 已原生支持图片延迟加载（<code>loading=&quot;lazy&quot;</code> 属性），无需插件。但延迟 JS 需要插件实现。</p><h3 id="_19-7-2-操作方法-配置延迟-js" tabindex="-1">19.7.2 操作方法：配置延迟 JS <a class="header-anchor" href="#_19-7-2-操作方法-配置延迟-js" aria-label="Permalink to &quot;19.7.2 操作方法：配置延迟 JS&quot;">​</a></h3><p>Autoptimize 的「异步加载 JavaScript」是简化版；更精细的控制用「Flying Scripts」或 WP Rocket 的「Delay JavaScript execution」功能：</p><ol><li>安装并启用 <code>Flying Scripts</code>。</li><li>进入「设置 → Flying Scripts」。</li><li>「Include Keywords」：填入非关键 JS 的关键词（如 <code>analytics</code>、<code>gtag</code>、<code>facebook-pixel</code>、<code>hotjar</code>）。</li><li>「Timeout」：设置延迟时间（如 5 秒），或选择「用户交互后」。</li><li>保存后，匹配的 JS 会在页面加载完成后延迟执行。</li></ol><p><img src="'+p+'" alt="图 19-7：Flying Scripts 的延迟 JS 关键词配置"></p><p><em>图 19-7：把统计代码、社交分享按钮等非关键 JS 延迟，首屏速度立竿见影。</em></p><h3 id="_19-7-3-常见问题" tabindex="-1">19.7.3 常见问题 <a class="header-anchor" href="#_19-7-3-常见问题" aria-label="Permalink to &quot;19.7.3 常见问题&quot;">​</a></h3><p><strong>问：延迟 JS 后，统计代码会不会漏数据？</strong> 会。如果用户 5 秒内就离开页面，延迟执行的统计代码可能来不及发送数据。对统计精度要求高的站点，可把延迟时间缩短到 2 秒，或只延迟「非关键」统计（如热图工具），核心统计（如 Google Analytics）保持正常加载。</p><h2 id="_19-8-用-query-monitor-定位性能瓶颈" tabindex="-1">19.8 用 Query Monitor 定位性能瓶颈 <a class="header-anchor" href="#_19-8-用-query-monitor-定位性能瓶颈" aria-label="Permalink to &quot;19.8 用 Query Monitor 定位性能瓶颈&quot;">​</a></h2><h3 id="_19-8-1-原理说明" tabindex="-1">19.8.1 原理说明 <a class="header-anchor" href="#_19-8-1-原理说明" aria-label="Permalink to &quot;19.8.1 原理说明&quot;">​</a></h3><p>所有缓存与优化都是「对症下藥」——而 Query Monitor 就是那台「诊断仪」。它在页面底部（或管理员工具栏）展示本次请求的完整性能画像：数据库查询次数与耗时、每个查询由哪个插件触发、HTTP 请求、内存峰值、加载了哪些 CSS/JS、是否命中缓存。</p><h3 id="_19-8-2-操作方法-读性能面板" tabindex="-1">19.8.2 操作方法：读性能面板 <a class="header-anchor" href="#_19-8-2-操作方法-读性能面板" aria-label="Permalink to &quot;19.8.2 操作方法：读性能面板&quot;">​</a></h3><ol><li>安装并启用 <code>Query Monitor</code>（官方库免费）。</li><li>以管理员身份访问前台任意页面，页面底部会出现性能面板（普通访客看不到）。</li><li>重点看四个区域： <ul><li><strong>查询（Queries）</strong>：按调用者（插件/主题/核心）分组。某个插件单独贡献了 50+ 次查询？它就是优化目标。</li><li><strong>按组件的查询</strong>：直接列出「每个插件的查询耗时占比」，一眼定位最重的插件。</li><li><strong>HTTP API 调用</strong>：某些插件每次页面加载都请求外部 API（如字体、授权验证），这一项会显示耗时——超过 500ms 的外部请求就是首屏杀手。</li><li><strong>缓存命中</strong>：确认对象缓存是否生效（命中率高说明 Redis 配置正确）。</li></ul></li></ol><p><img src="'+c+'" alt="图 19-8：Query Monitor 的查询面板，按插件分组展示"></p><p><em>图 19-8：按组件分组后，哪个插件拖慢了站点一目了然。</em></p><h3 id="_19-8-3-常见问题" tabindex="-1">19.8.3 常见问题 <a class="header-anchor" href="#_19-8-3-常见问题" aria-label="Permalink to &quot;19.8.3 常见问题&quot;">​</a></h3><p><strong>问：Query Monitor 本身会拖慢网站吗？</strong> 它只对登录管理员生效，且收集数据有少量开销。生产站排查完可以停用；但因为它只影响管理员，留着通常也无妨。</p><p><strong>问：面板显示「对象缓存未启用」但我装了 Redis 插件？</strong> 检查「设置 → Redis」的状态是否为「已连接」，以及 <code>wp-content/object-cache.php</code> 文件是否存在。文件被安全插件或主机商清理工具误删是常见原因。</p><h2 id="_19-9-常见问题速查" tabindex="-1">19.9 常见问题速查 <a class="header-anchor" href="#_19-9-常见问题速查" aria-label="Permalink to &quot;19.9 常见问题速查&quot;">​</a></h2><h3 id="_19-9-1-缓存导致登录用户看到他人页面" tabindex="-1">19.9.1 缓存导致登录用户看到他人页面 <a class="header-anchor" href="#_19-9-1-缓存导致登录用户看到他人页面" aria-label="Permalink to &quot;19.9.1 缓存导致登录用户看到他人页面&quot;">​</a></h3><p><strong>现象</strong>：用户 A 登录后访问后台，退出登录；用户 B 在同一台电脑访问前台，看到用户 A 的「欢迎回来」或购物车内容。</p><p><strong>原因</strong>：页面缓存插件错误地缓存了「登录用户的页面」，或缓存键未区分用户身份。</p><p><strong>排查与修复</strong>：</p><ol><li>检查 WP Super Cache「高级 → 不缓存已登录用户的页面」是否勾选。</li><li>检查「高级 → 已知用户」设置，确保「缓存已知用户」未勾选。</li><li>检查是否有插件（如某些会员插件）强制输出「私有缓存」头，与页面缓存冲突。</li><li>清空全部缓存，重新测试。</li></ol><p><strong>预防</strong>：任何涉及用户隐私的页面（购物车、会员中心、订单页）必须设置 <code>Cache-Control: private, no-cache</code>，或在缓存插件中把这些页面加入「不缓存列表」。</p><h3 id="_19-9-2-改-css-不生效-缓存层级排查顺序" tabindex="-1">19.9.2 改 CSS 不生效，缓存层级排查顺序 <a class="header-anchor" href="#_19-9-2-改-css-不生效-缓存层级排查顺序" aria-label="Permalink to &quot;19.9.2 改 CSS 不生效，缓存层级排查顺序&quot;">​</a></h3><p><strong>现象</strong>：修改了主题的 <code>style.css</code>，刷新前台样式没变。</p><p><strong>排查顺序</strong>（从近到远）：</p><ol><li><strong>浏览器缓存</strong>：强制刷新（Ctrl+F5 或 Cmd+Shift+R），或开无痕窗口测试。</li><li><strong>页面缓存插件</strong>：到 WP Super Cache「内容 → 删除缓存」清空。</li><li><strong>CDN 缓存</strong>：如果用了 Cloudflare，到控制台「缓存 → 清除所有缓存」。</li><li><strong>服务器 OPcache</strong>：重启 PHP-FPM（<code>sudo systemctl restart php8.3-fpm</code>）。</li><li><strong>对象缓存</strong>：到「设置 → Redis」点击「刷新缓存」。</li><li><strong>主题/插件内置缓存</strong>：某些主题（如 Avada、Divi）有自己的缓存系统，需到主题设置里清空。</li></ol><p><strong>终极验证</strong>：在 <code>style.css</code> 文件内容里加一行注释 <code>/* cache-test-20261004 */</code>，查看页面源代码里引用的 CSS 文件内容是否包含这行注释。如果包含但样式仍未变，说明是 CSS 选择器优先级问题，不是缓存问题。</p><h3 id="_19-9-3-压缩合并破坏-js-依赖顺序" tabindex="-1">19.9.3 压缩合并破坏 JS 依赖顺序 <a class="header-anchor" href="#_19-9-3-压缩合并破坏-js-依赖顺序" aria-label="Permalink to &quot;19.9.3 压缩合并破坏 JS 依赖顺序&quot;">​</a></h3><p><strong>现象</strong>：开启 Autoptimize 合并后，控制台报错 <code>$ is not defined</code> 或 <code>jQuery is not defined</code>。</p><p><strong>原因</strong>：合并后的文件中，依赖 jQuery 的插件代码排在 jQuery 库之前执行。</p><p><strong>修复</strong>：</p><ol><li>到 Autoptimize 设置，「排除 JavaScript 文件」中加入 <code>jquery.js</code>（或 <code>jquery.min.js</code>），让 jQuery 保持独立加载且最先执行。</li><li>或关闭「合并 JS 文件」，只保留「优化 JavaScript 代码」（压缩）。</li><li>或把出问题的插件 JS 加入排除列表，单独加载。</li></ol><p><img src="'+g+`" alt="图 19-9：Autoptimize 的排除列表配置"></p><p><em>图 19-9：把 jQuery 与问题插件加入排除列表，是解决依赖顺序破坏的最快方法。</em></p><h3 id="_19-9-4-opcache-没开启导致所有优化效果打折" tabindex="-1">19.9.4 OPcache 没开启导致所有优化效果打折 <a class="header-anchor" href="#_19-9-4-opcache-没开启导致所有优化效果打折" aria-label="Permalink to &quot;19.9.4 OPcache 没开启导致所有优化效果打折&quot;">​</a></h3><p><strong>现象</strong>：页面缓存、对象缓存都配好了，但首次生成缓存的页面仍然很慢（TTFB 超过 1 秒）。</p><p><strong>排查</strong>：OPcache 是 PHP 层的加速，不属于插件范畴，但它是所有优化的地基。检查方法：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 命令行检查（需服务器权限）。</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出中应包含 &quot;with Zend OPcache v8.3.x&quot;</span></span></code></pre></div><p>或在网站根目录放一个 <code>phpinfo.php</code>（内容为 <code>&lt;?php phpinfo();</code>），浏览器访问后搜索「Zend OPcache」，确认 <code>opcache.enable</code> 为 On。<strong>用完立即删除该文件</strong>——phpinfo 泄露大量服务器信息。</p><p>如果未开启，参考<a href="./03-server-environment">第 03 章</a>的 PHP 配置部分，在 <code>php.ini</code> 中启用 <code>zend_extension=opcache</code> 并设置 <code>opcache.memory_consumption=256</code>。</p><h2 id="本章总结" tabindex="-1">本章总结 <a class="header-anchor" href="#本章总结" aria-label="Permalink to &quot;本章总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>关键动作</th><th>易错点</th></tr></thead><tbody><tr><td>缓存分层</td><td>浏览器 → CDN → 页面 → 对象 → OPcache，五层叠加</td><td>各层独立配置，不要指望一层解决所有问题</td></tr><tr><td>页面缓存</td><td>WP Super Cache 简单模式 + 预缓存 + 垃圾回收</td><td>登录用户不缓存；预缓存间隔视内容更新频率</td></tr><tr><td>对象缓存</td><td>服务器装 Redis → 启用 Redis Object Cache 插件</td><td>命中率应 &gt;90%；插件需用标准 API 才能受益</td></tr><tr><td>数据库优化</td><td>限制修订版本 + 定期清理回收站/瞬态</td><td>清理前备份；重要文章手动导出历史版本</td></tr><tr><td>压缩合并</td><td>压缩推荐；合并视 HTTP 版本决定</td><td>HTTP/2 下合并收益小，副作用大</td></tr><tr><td>延迟加载</td><td>图片原生支持；延迟 JS 用插件</td><td>统计代码延迟可能漏数据，关键代码保持正常</td></tr><tr><td>缓存穿透</td><td>登录用户页面必须 private/no-cache</td><td>购物车/会员中心必须加入不缓存列表</td></tr><tr><td>样式不更新</td><td>按浏览器→插件→CDN→OPcache→对象缓存顺序排查</td><td>终极验证：在 CSS 里加注释看是否生效</td></tr><tr><td>JS 依赖破坏</td><td>jQuery 加入排除列表，或关闭合并</td><td>报错 <code>$ is not defined</code> 基本就是这个问题</td></tr></tbody></table><h2 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h2><p><strong>练-19-01（操作题）｜配置 WP Super Cache 并验证</strong></p><p>在练习站安装 WP Super Cache，按 19.2.1 完成简单模式 + 预缓存 + 垃圾回收配置。用无痕窗口访问首页，查看页面源代码底部是否有缓存注释；刷新后注释时间不变，截图证明缓存生效。</p><p><strong>练-19-02（操作题）｜对比对象缓存开启前后的查询数</strong></p><p>安装 Query Monitor 与 Redis Object Cache。先不开对象缓存，刷新后台「文章 → 所有文章」，用 Query Monitor 记录数据库查询次数；然后开启对象缓存，再次刷新同一页面，对比查询次数变化。解释为什么第二次查询次数大幅下降。</p><p><strong>练-19-03（分析题）｜HTTP/2 下是否需要合并</strong></p><p>用浏览器开发者工具（Network 面板）查看你的练习站：① 当前是 HTTP/1.1 还是 HTTP/2？② 首页加载了多少个 CSS 文件、多少个 JS 文件？③ 如果开启合并，预计减少多少请求？④ 结合 HTTP 版本，给出「是否合并」的结论，并说明理由。</p><p><strong>练-19-04（故障题）｜模拟并修复缓存穿透</strong></p><p>在练习站开启 WP Super Cache，登录管理员账号访问前台某页面，然后退出登录。用无痕窗口访问同一页面，观察是否看到「欢迎回来，管理员」等登录态信息。如果看到，说明缓存穿透；按 19.9.1 的排查顺序修复，直到无痕窗口看到的是纯匿名页面。</p><p><strong>练-19-05（综合题）｜为一个高并发博客设计缓存策略</strong></p><p>假设你维护一个日均 PV 50 万的科技博客，服务器配置为 4 核 8G，已开启 OPcache。请设计完整的缓存策略：① 页面缓存插件选哪个、预缓存间隔多少？② 是否上对象缓存、用 Redis 还是 Memcached？③ 是否用 CDN、缓存什么内容？④ 数据库优化策略（修订版本、清理频率）？⑤ 静态资源压缩合并策略？每一项说明「如果这一项不做，瓶颈会出现在哪一层」。</p>`,159)])])}const y=t(A,[["render",k]]);export{_ as __pageData,y as default};
